 14	/**
 15	 * Parses example code to extract statements and assertions.
 16	 *
 17	 * The parser recognizes several assertion formats:
 18	 * - Return value: `expression // => expected_value`
 19	 * - Output: `echo $var; // Output: expected_output`
 20	 * - Exception: `throw new Exception(); // throws Exception`
 21	 * - Exception with message: `throw new Exception("msg"); // throws Exception: msg`
 22	 *
 23	 * Lines without assertions become "smoke test" statements that just verify
 24	 * the code runs without errors.
 25	 */
 26	final class AssertionParser
 27	{
 28	    /** @var list<string> */
 29	    private const INCOMPLETE_PATTERNS = [
 30	        '/\.\s*$/',
 31	        '/,\s*$/',
 32	        '/\(\s*$/',
 33	        '/\[\s*$/',
 34	        '/\{\s*$/',
 35	        '/=>\s*$/',
 36	        '/\->\s*$/',
 37	        '/::\s*$/',
 38	        '/&&\s*$/',
 39	        '/\|\|\s*$/',
 40	        '/\?\s*$/',
 41	    ];
 42	
 43	    /**
 44	     * Parse example code and extract assertions.
 45	     *
 46	     * Supported formats:
 47	     * - `expression // => expected_value`
 48	     * - `echo $var; // Output: expected_output`
 49	     * - `throw new Exception(); // throws Exception`
 50	     * - `throw new Exception("msg"); // throws Exception: msg`
 51	     *
 52	     * @param Example $example the example to parse
 53	     * @return ParsedExample the parsed example with statements
 54	     */
 55	    public function parse(Example $example): ParsedExample
 56	    {
 57	        $lines = explode("\n", $example->code);
 58	        $statements = [];
 59	        $currentCode = '';
 60	        $lineNum = 0;
 61	
 62	        foreach ($lines as $index => $line) {
 63	            $trimmed = trim($line);
 64	            if ($trimmed === '') {
 65	                continue;
 66	            }
 67	
 68	            $lineNum = $index + 1;
 69	            $statement = $this->parseLine($trimmed, $currentCode, $lineNum);
 70	            if ($statement !== null) {
 71	                $statements[] = $statement;
 72	                $currentCode = '';
 73	                continue;
 74	            }
 75	
 76	            if ($this->isIncompleteLine($trimmed)) {
 77	                $currentCode .= $trimmed . ' ';
 78	                continue;
 79	            }
 80	
 81	            $statements[] = new Statement($currentCode . $trimmed, null, $lineNum);
 82	            $currentCode = '';
 83	        }
 84	
 85	        if ($currentCode !== '') {
 86	            $statements[] = new Statement(trim($currentCode), null, $lineNum);
 87	        }
 88	
 89	        return new ParsedExample($example, $statements);
 90	    }
 91	
 92	    /**
 93	     * Parses one line into an asserted statement, or null when it carries no assertion.
 94	     *
 95	     * @param string $trimmed the trimmed source line
 96	     * @param string $currentCode code buffered from earlier incomplete lines
 97	     * @param int $lineNum line number within the example
 98	     */
 99	    public function parseLine(string $trimmed, string $currentCode, int $lineNum): ?Statement
100	    {
101	        $matches = [];
102	        if (preg_match('/^(.+?)\s*\/\/\s*=>\s*(.+)$/', $trimmed, $matches) === 1) {
103	            return new Statement($currentCode . trim($matches[1]), new Assertion(AssertionKind::RETURN_VALUE, trim($matches[2])), $lineNum);
104	        }
105	
106	        if (preg_match('/^(.+?)\s*\/\/\s*Output:\s*(.*)$/', $trimmed, $matches) === 1) {
107	            return new Statement($currentCode . trim($matches[1]), new Assertion(AssertionKind::OUTPUT, $matches[2]), $lineNum);
108	        }
109	
110	        if (preg_match('/^(.+?)\s*\/\/\s*throws\s+(\S+?)(?::\s*(.*))?$/', $trimmed, $matches) === 1) {
111	            $message = isset($matches[3]) ? trim($matches[3]) : null;
112	
113	            return new Statement($currentCode . trim($matches[1]), new Assertion(AssertionKind::EXCEPTION, $matches[2], $message), $lineNum);
114	        }
115	
116	        return null;
117	    }
118	
119	    /**
120	     * Reports whether the line is likely continued on the next one.
121	     *
122	     * A line ending in an operator or an opening bracket has no complete
123	     * meaning on its own, so it is buffered until the statement finishes.
124	     */
125	    public function isIncompleteLine(string $line): bool
126	    {
127	        foreach (self::INCOMPLETE_PATTERNS as $pattern) {
128	            if (preg_match($pattern, $line) === 1) {
129	                return true;
130	            }
131	        }
132	
133	        return false;
134	    }
135	}

