 37	/**
 38	 * Extracts Example objects from Target docblocks.
 39	 *
 40	 * Supports both at-example tags followed by indented code,
 41	 * and triple-backtick php code fences in markdown style.
 42	 */
 43	final class ExampleExtractor
 44	{
 45	    /**
 46	     * Extracts all examples from a target's docblock.
 47	     *
 48	     * At-example blocks are yielded before code fences, and the index runs
 49	     * across both, which is the order k-kinzal/doctest-php established.
 50	     *
 51	     * @param Target $target the target containing the docblock
 52	     * @return Generator<int, Example> examples found in the docblock
 53	     */
 54	    public function extract(Target $target): Generator
 55	    {
 56	        $docblock = $this->cleanDocblock($target->docblock);
 57	        $index = 0;
 58	
 59	        yield from $this->extractExampleTags($docblock, $target, $index);
 60	        yield from $this->extractCodeFences($docblock, $target, $index);
 61	    }
 62	
 63	    /**
 64	     * Strips the docblock frame and one leading space per line.
 65	     */
 66	    public function cleanDocblock(string $docblock): string
 67	    {
 68	        $body = preg_replace('/^\/\*\*\s*|\s*\*\/$/s', '', $docblock) ?? $docblock;
 69	        $cleaned = [];
 70	        foreach (explode("\n", $body) as $line) {
 71	            $cleaned[] = preg_replace('/^\s*\*\s?/', '', $line) ?? $line;
 72	        }
 73	
 74	        return implode("\n", $cleaned);
 75	    }
 76	
 77	    /**
 78	     * Yields the examples introduced by at-example tags.
 79	     *
 80	     * @param int $index running example index, advanced for each example yielded
 81	     * @return Generator<int, Example>
 82	     */
 83	    public function extractExampleTags(string $docblock, Target $target, int &$index): Generator
 84	    {
 85	        $parts = preg_split('/(?=@example\b)/', $docblock, -1, PREG_SPLIT_NO_EMPTY);
 86	        if ($parts === false) {
 87	            return;
 88	        }
 89	
 90	        foreach ($parts as $part) {
 91	            if (!str_starts_with(trim($part), '@example')) {
 92	                continue;
 93	            }
 94	
 95	            $code = $this->tagCode($part);
 96	            if ($code === '') {
 97	                continue;
 98	            }
 99	
100	            $offset = strpos($docblock, $part);
101	
102	            yield new Example(
103	                $code,
104	                $target,
105	                $this->calculateLineNumber($docblock, $offset === false ? 0 : $offset, $target->line),
106	                $index++,
107	                $this->tagDescription($part),
108	            );
109	        }
110	    }
111	
112	    /**
113	     * Returns the description written on an at-example tag line, if any.
114	     */
115	    public function tagDescription(string $part): ?string
116	    {
117	        $lines = explode("\n", $part);
118	        $firstLine = array_shift($lines);
119	        $match = [];
120	        if (preg_match('/@example\s+(.+)$/', $firstLine, $match) === 1) {
121	            $description = trim($match[1]);
122	
123	            return $description === '' ? null : $description;
124	        }
125	
126	        return null;
127	    }
128	
129	    /**
130	     * Returns the code lines below an at-example tag, up to the next tag.
131	     */
132	    public function tagCode(string $part): string
133	    {
134	        $lines = explode("\n", $part);
135	        array_shift($lines);
136	
137	        $codeLines = [];
138	        foreach ($lines as $line) {
139	            $trimmedLine = trim($line);
140	            if (preg_match('/^@\w+/', $trimmedLine) === 1) {
141	                break;
142	            }
143	
144	            if ($codeLines === [] && $trimmedLine === '') {
145	                continue;
146	            }
147	
148	            $codeLines[] = $line;
149	        }
150	
151	        while ($codeLines !== [] && trim(end($codeLines)) === '') {
152	            array_pop($codeLines);
153	        }
154	
155	        return trim(implode("\n", $codeLines));
156	    }
157	
158	    /**
159	     * Yields the examples written as triple-backtick php code fences.
160	     *
161	     * @param int $index running example index, advanced for each example yielded
162	     * @return Generator<int, Example>
163	     */
164	    public function extractCodeFences(string $docblock, Target $target, int &$index): Generator
165	    {
166	        $matches = [];
167	        if (preg_match_all('/```php\s*\n(.*?)```/s', $docblock, $matches, PREG_SET_ORDER | PREG_OFFSET_CAPTURE) === false) {
168	            return;
169	        }
170	
171	        foreach ($matches as $match) {
172	            $code = trim($match[1][0]);
173	            if ($code === '') {
174	                continue;
175	            }
176	
177	            yield new Example($code, $target, $this->calculateLineNumber($docblock, $match[0][1], $target->line), $index++);
178	        }
179	    }
180	
181	    /**
182	     * Returns the source line an example body starts on.
183	     */
184	    public function calculateLineNumber(string $docblock, int $offset, int $baseLine): int
185	    {
186	        $beforeMatch = substr($docblock, 0, $offset);
187	        $linesBeforeMatch = substr_count($beforeMatch, "\n");
188	
189	        return $baseLine + $linesBeforeMatch + 1;
190	    }
191	}

