 31	 */
 32	final class ExpressionEvaluator
 33	{
 34	    /** @var list<string> */
 35	    private const NO_RETURN_PATTERNS = [
 36	        '/^\$\w+\s*=/',
 37	        '/^echo\s/',
 38	        '/^print\s/',
 39	        '/^return\s/',
 40	        '/^if\s*\(/',
 41	        '/^for\s*\(/',
 42	        '/^foreach\s*\(/',
 43	        '/^while\s*\(/',
 44	        '/^do\s*\{/',
 45	        '/^switch\s*\(/',
 46	        '/^try\s*\{/',
 47	        '/^throw\s/',
 48	        '/^class\s/',
 49	        '/^function\s/',
 50	        '/^new\s+\w+\s*;$/',
 51	    ];
