 63	    {
 64	        $__doctest_vars__ = $context->getVariables();
 65	        $__doctest_code__ = $this->codeNeedsReturn($code) ? 'return ' . $code . ';' : $code;
 66	
 67	        ob_start();
 68	
 69	        try {
 70	            extract($__doctest_vars__, EXTR_SKIP);
 71	            $__doctest_result__ = eval($__doctest_code__);
 72	            $__doctest_all_vars__ = get_defined_vars();
 73	            unset(
 74	                $__doctest_all_vars__['__doctest_vars__'],
 75	                $__doctest_all_vars__['__doctest_code__'],
 76	                $__doctest_all_vars__['__doctest_result__'],
 77	                $__doctest_all_vars__['__doctest_all_vars__'],
 78	                $__doctest_all_vars__['code'],
 79	                $__doctest_all_vars__['context'],
 80	            );
 81	            $context->setVariables($__doctest_all_vars__);
 82	            $output = ob_get_contents();
 83	            $context->lastOutput = $output === false ? '' : $output;
 84	
 85	            return new Evaluation($__doctest_result__);
 86	        } catch (Throwable $error) {
 87	            return new Evaluation(null, $error);
 88	        } finally {
 89	            ob_end_clean();
 90	        }
 91	    }
