 27	final class FileScanner
 28	{
 29	    /**
 30	     * @param Configuration $config the configuration specifying directories and exclusions
 31	     */
 32	    public function __construct(
 33	        /** @readonly */
 34	        private Configuration $config,
 35	    ) {
 36	    }
 37	
 38	    /**
 39	     * Scans all configured sources and yields PHP file paths.
 40	     *
 41	     * Iterates through configured directories recursively, as well as
 42	     * individual files, filtering based on exclude patterns.
 43	     *
 44	     * @return Generator<int, string> absolute paths to PHP files
 45	     */
 46	    public function scan(): Generator
 47	    {
 48	        foreach ($this->config->getDirectories() as $directory) {
 49	            if (!is_dir($directory)) {
 50	                continue;
 51	            }
 52	
 53	            yield from $this->scanDirectory($directory);
 54	        }
 55	
 56	        foreach ($this->config->getFiles() as $file) {
 57	            if (is_file($file) && $this->shouldInclude($file)) {
 58	                yield $file;
 59	            }
 60	        }
 61	    }
 62	
 63	    /**
 64	     * Yields the PHP files below one directory.
 65	     *
 66	     * @return Generator<int, string>
 67	     */
 68	    public function scanDirectory(string $directory): Generator
 69	    {
 70	        $iterator = new RecursiveIteratorIterator(
 71	            new RecursiveDirectoryIterator($directory, RecursiveDirectoryIterator::SKIP_DOTS),
 72	        );
 73	
 74	        /** @var RegexIterator<int, SplFileInfo, RecursiveIteratorIterator<RecursiveDirectoryIterator>> $phpFiles */
 75	        $phpFiles = new RegexIterator($iterator, '/\.php$/');
 76	
 77	        $paths = [];
 78	        foreach ($phpFiles as $file) {
 79	            $path = $file->getPathname();
 80	            if ($this->shouldInclude($path)) {
 81	                $paths[] = $path;
 82	            }
 83	        }
 84	
 85	        sort($paths);
 86	
 87	        yield from $paths;
 88	    }
 89	
 90	    /**
 91	     * Reports whether a discovered path survives the configured exclude patterns.
 92	     */
 93	    public function shouldInclude(string $path): bool
 94	    {
 95	        foreach ($this->config->getExcludePatterns() as $pattern) {
 96	            if (fnmatch($pattern, $path) || fnmatch('*' . $pattern, $path)) {
 97	                return false;
 98	            }
 99	        }
100	
101	        return true;
102	    }
