 51	    public function bootstrap(
 52	        PhpUnitConfiguration $configuration,
 53	        Facade $facade,
 54	        ParameterCollection $parameters,
 55	    ): void {
 56	        $config = ConfigurationLoader::fromParameters($parameters, self::basePath($configuration));
