 71	     * @param PhpUnitConfiguration $configuration the configuration of the running test runner
 72	     */
 73	    public static function basePath(PhpUnitConfiguration $configuration): string
 74	    {
 75	        $configFile = $configuration->hasConfigurationFile() ? $configuration->configurationFile() : '';
 76	        if ($configFile !== '') {
 77	            return dirname($configFile);
 78	        }
 79	
 80	        $workingDirectory = getcwd();
 81	
 82	        return $workingDirectory === false ? '' : $workingDirectory;
 83	    }
