15	/**
16	 * Creates a PHP parser for both nikic/php-parser 4 and 5.
17	 *
18	 * An adaptation the port needs: k-kinzal/doctest-php calls
19	 * createForNewestSupportedVersion(), which only php-parser 5 ships, while this
20	 * package also supports php-parser 4. The factory is inspected with reflection
21	 * and the available method is invoked, so the bridge stays valid for either
22	 * major without naming a method only one of them has.
23	 *
24	 * @visibility parent
25	 */
26	final class ParserFactoryBridge
27	{
28	    /**
29	     * Returns a parser for the newest PHP version the installed parser supports.
30	     *
31	     * @throws RuntimeException when the factory exposes no supported creation method or produces no parser
32	     */
33	    public function create(): Parser
34	    {
35	        $factory = new ParserFactory();
36	        $reflection = new ReflectionClass($factory);
37	
38	        try {
39	            if ($reflection->hasMethod('createForNewestSupportedVersion')) {
40	                $created = $reflection->getMethod('createForNewestSupportedVersion')->invoke($factory);
41	            } else {
42	                $created = $reflection->getMethod('create')->invoke($factory, constant(ParserFactory::class . '::PREFER_PHP7'));
43	            }
44	        } catch (ReflectionException $exception) {
45	            throw new RuntimeException('The installed nikic/php-parser version exposes no supported parser factory method.', 0, $exception);
46	        }
47	
48	        if (!$created instanceof Parser) {
49	            throw new RuntimeException('The installed nikic/php-parser version produced no parser instance.');
50	        }
51	
52	        return $created;
53	    }
54	}

