 54	     *
 55	     * @return mixed the value of the requested property
 56	     */
 57	    public function __get(string $name): mixed
 58	    {
 59	        return match ($name) {
 60	            'passed' => $this->passed,
 61	            'message' => $this->message,
 62	            'statement' => $this->statement,
 63	            'expected' => $this->expected,
 64	            'actual' => $this->actual,
 65	            default => null,
 66	        };
