 71	     *
 72	     * For passing assertions, returns 'OK'. For failing assertions, includes
 73	     * the code, expected value, actual value, and error message.
 74	     */
 75	    public function getDetailedMessage(): string
 76	    {
 77	        if ($this->passed) {
 78	            return 'OK';
 79	        }
 80	
 81	        $parts = ['Assertion failed', 'Code: ' . $this->statement->code];
 82	        if ($this->expected !== null) {
 83	            $parts[] = 'Expected: ' . $this->formatValue($this->expected);
 84	        }
 85	
 86	        if ($this->actual !== null) {
 87	            $parts[] = 'Actual: ' . $this->formatValue($this->actual);
 88	        }
 89	
 90	        if ($this->message !== '') {
 91	            $parts[] = 'Message: ' . $this->message;
 92	        }
