  9	/**
 10	 * Represents a target (file, class, method, or function) that may contain docblock examples.
 11	 *
 12	 * A Target encapsulates all information needed to identify and process a documented
 13	 * element in the source code, including its type, location, and associated docblock.
 14	 *
 15	 * @property-read string $type
 16	 * @property-read string $filePath
 17	 * @property-read string $docblock
 18	 * @property-read string $name
 19	 * @property-read int $line
 20	 * @property-read ?string $namespace
 21	 * @property-read ?string $className
 22	 * @property-read bool $isStatic
 23	 */
 24	final class Target
 25	{
 26	    /**
 27	     * @param string $type the kind of this target, one of the TargetKind constants
 28	     * @param string $filePath absolute path to the source file
 29	     * @param string $docblock the raw docblock content including delimiters
 30	     * @param string $name the name of the target, such as a class or method name
 31	     * @param int $line line number where the docblock starts
 32	     * @param string|null $namespace the namespace of the target, if applicable
 33	     * @param string|null $className the class name, if the target is a method
 34	     * @param bool $isStatic whether the target is a static method
 35	     */
 36	    public function __construct(
 37	        /** @readonly */
 38	        private string $type,
 39	        /** @readonly */
 40	        private string $filePath,
 41	        /** @readonly */
 42	        private string $docblock,
 43	        /** @readonly */
 44	        private string $name,
 45	        /** @readonly */
 46	        private int $line,
 47	        /** @readonly */
 48	        private ?string $namespace = null,
 49	        /** @readonly */
 50	        private ?string $className = null,
 51	        /** @readonly */
 52	        private bool $isStatic = false,
 53	    ) {
 54	    }
 55	
 56	    /**
 57	     * Provides read-only access to the immutable properties.
 58	     *
 59	     * @return mixed the value of the requested property
 60	     */
 61	    public function __get(string $name): mixed
 62	    {
 63	        return match ($name) {
 64	            'type' => $this->type,
 65	            'filePath' => $this->filePath,
 66	            'docblock' => $this->docblock,
 67	            'name' => $this->name,
 68	            'line' => $this->line,
 69	            'namespace' => $this->namespace,
 70	            'className' => $this->className,
 71	            'isStatic' => $this->isStatic,
 72	            default => null,
 73	        };
 74	    }
 75	
 76	    /**
 77	     * Returns the fully qualified name of the target.
 78	     */
 79	    public function getFullyQualifiedName(): string
 80	    {
 81	        $prefix = $this->namespace !== null ? $this->namespace . '\\' : '';
 82	        if ($this->type === TargetKind::FILE) {
 83	            return $this->filePath;
 84	        }
 85	
 86	        if ($this->type === TargetKind::CLASS_LIKE) {
 87	            return $prefix . $this->name;
 88	        }
 89	
 90	        if ($this->type === TargetKind::FUNCTION) {
 91	            return $prefix . $this->name . '()';
 92	        }
 93	
 94	        return $prefix . $this->className . '::' . $this->name . '()';
 95	    }
 96	
 97	    /**
 98	     * Returns the short (unqualified) name of the target.
 99	     */
100	    public function getShortName(): string
101	    {
102	        if ($this->type === TargetKind::FILE) {
103	            return basename($this->filePath);
104	        }
105	
106	        if ($this->type === TargetKind::CLASS_LIKE) {
107	            return $this->name;
108	        }
109	
110	        if ($this->type === TargetKind::FUNCTION) {
111	            return $this->name . '()';
112	        }
113	
114	        return $this->className . '::' . $this->name . '()';
115	    }
116	}
