 24	     * @param Throwable|null $error what the code raised, null when it completed
 25	     */
 26	    public function __construct(
 27	        /** @readonly */
 28	        private mixed $value = null,
 29	        /** @readonly */
 30	        private ?Throwable $error = null,
 31	    ) {
 32	    }
 33	
 34	    /**
