44	     *
45	     * @return list<string>
46	     */
47	    public function testsForRange(string $file, int $startLine, int $endLine): array
48	    {
49	        $tests = [];
50	        foreach ($this->lineTests[$file] ?? [] as $line => $lineTests) {
51	            if ($line >= $startLine && $line <= $endLine) {
52	                foreach (array_keys($lineTests) as $test) {
53	                    $tests[$test] = true;
54	                }
55	            }
56	        }
57	
