 25	/**
 26	 * Reads a PHPUnit XML coverage report directory.
 27	 *
 28	 * The report produced by the PHPUnit option "--coverage-xml" attributes
 29	 * every covered line to the tests that executed it, which is what links
 30	 * methods to their covering test cases.
 31	 */
 32	final class CoverageReader
 33	{
 34	    /** @readonly */
 35	    private DocGenPathResolver $pathResolver;
 36	
 37	    /**
 38	     * Creates a coverage reader with path resolution support.
 39	     */
 40	    public function __construct(?DocGenPathResolver $pathResolver = null)
 41	    {
 42	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
 43	    }
 44	
 45	    /**
 46	     * Reads all per-file coverage reports below a directory.
 47	     *
 48	     * File paths in the report are relative to the report's own source
 49	     * directory, so they are rebased onto the project root using the
 50	     * source attribute of index.xml.
 51	     *
 52	     * @throws DocGenException when the directory does not exist
 53	     */
 54	    public function read(string $directory, string $projectRoot): CoverageIndex
 55	    {
 56	        if (!is_dir($directory)) {
 57	            throw new DocGenException(sprintf('Coverage report directory not found: %s', $directory));
 58	        }
 59	
 60	        $sourcePrefix = $this->sourcePrefix($directory, $projectRoot);
 61	        $index = new CoverageIndex();
 62	        $queue = [$directory];
 63	        for ($position = 0; $position < count($queue); $position++) {
 64	            $entries = scandir($queue[$position]);
 65	            foreach ($entries === false ? [] : $entries as $entry) {
 66	                if ($entry === '.' || $entry === '..') {
 67	                    continue;
 68	                }
 69	
 70	                $path = $queue[$position] . '/' . $entry;
 71	                if (is_dir($path)) {
 72	                    $queue[] = $path;
 73	                } elseif (str_ends_with($entry, '.xml') && $entry !== 'index.xml') {
 74	                    $this->readReportFile($path, $sourcePrefix, $index);
 75	                }
 76	            }
 77	        }
 78	
 79	        return $index;
 80	    }
 81	
 82	    /**
 83	     * Determines the project-relative prefix of the report's source root.
 84	     */
 85	    public function sourcePrefix(string $directory, string $projectRoot): string
 86	    {
 87	        $indexPath = $directory . '/index.xml';
 88	        if (!is_file($indexPath)) {
 89	            return '';
 90	        }
 91	
 92	        $document = new DOMDocument();
 93	        if (@$document->load($indexPath) === false) {
 94	            return '';
 95	        }
 96	
 97	        foreach ($document->getElementsByTagName('project') as $project) {
 98	            $source = $project->getAttribute('source');
 99	            if ($source !== '') {
100	                $relative = $this->pathResolver->relative($projectRoot, $source);
101	
102	                return $relative === $source ? '' : trim($relative, '/');
103	            }
104	        }
105	
106	        return '';
107	    }
108	
109	    /**
110	     * Reads one per-file coverage report into the index.
111	     *
112	     * Newer report versions split the file location into a directory path
113	     * attribute and a base name; older versions carry one full name.
114	     */
115	    public function readReportFile(string $path, string $sourcePrefix, CoverageIndex $index): void
116	    {
117	        $document = new DOMDocument();
118	        if (@$document->load($path) === false) {
119	            return;
120	        }
121	
122	        foreach ($document->getElementsByTagName('file') as $file) {
123	            if ($file->getAttribute('name') === '') {
124	                continue;
125	            }
126	
127	            $partial = ltrim($file->getAttribute('name'), '/');
128	            if ($file->getAttribute('path') !== '') {
129	                $partial = trim($file->getAttribute('path'), '/') . '/' . $partial;
130	            }
131	
132	            $relativePath = $sourcePrefix !== '' ? $sourcePrefix . '/' . $partial : $partial;
