144	            $number = (int) $line->getAttribute('nr');
145	            $tests = [];
146	            foreach ($line->getElementsByTagName('covered') as $covered) {
147	                if ($covered->getAttribute('by') !== '') {
148	                    $tests[] = $this->normalizeTestId($covered->getAttribute('by'));
149	                }
150	            }
151	
152	            if ($number > 0 && $tests !== []) {
153	                $index->addLine($relativePath, $number, $tests);
154	            }
155	        }
156	    }
157	
158	    /**
