namespace Infection\Mutator\Removal;

use function array_keys;
use function array_values;
use function count;
use Infection\Mutator\Definition;
use Infection\Mutator\GetMutatorName;
use Infection\Mutator\Mutator;
use Infection\Mutator\MutatorCategory;
use Infection\Mutator\NodeAttributes;
use PhpParser\Node;

/**
 * @internal
 *
 * @implements Mutator<Node\Expr\Match_>
 */
final class MatchArmRemoval implements Mutator
{
    use GetMutatorName;

    public static function getDefinition(): Definition
    {
        return new Definition(
            <<<'TXT'
                Removes `match arm`s from `match`.

                ```php
                match ($x) {
                    'cond1', 'cond2' => true,
                    default => throw new \Exception(),
                };
                ```

                Will be mutated to:

                ```php
                match ($x) {
                    'cond1' => true,
                    default => throw new \Exception(),
                };
                ```

                ```php
                match ($x) {
                    'cond2' => true,
                    default => throw new \Exception(),
                };
                ```

                And:
                ```php
                match ($x) {
                    default => throw new \Exception(),
                };
                ```
                TXT,
            MutatorCategory::SEMANTIC_REDUCTION,
            null,
            <<<'DIFF'
                match ($x) {
                -   0 => false,
                    1 => true,
                    2 => null,
                    default => throw new \Exception(),
                };
                DIFF,
        );
    }

    public function canMutate(Node $node): bool
    {
        return $node instanceof Node\Expr\Match_
            && count($node->arms) > 1;
    }

    /**
     * @psalm-mutation-free
     *
     * @return iterable<Node\Expr\Match_>
     */
    public function mutate(Node $node): iterable
    {
        foreach ($node->arms as $i => $arm) {
            $arms = $node->arms;

    {
        foreach ($node->arms as $i => $arm) {
            $arms = $node->arms;

            $armConds = $arm->conds ?? [];

            if (count($armConds) > 1) {
                foreach (array_keys($armConds) as $j) {
                    $conds = $armConds;

                    unset($conds[$j]);

                    $arms[$i] = new Node\MatchArm(array_values($conds), $arm->body, NodeAttributes::getAllExceptOriginalNode($node));

                    yield new Node\Expr\Match_($node->cond, $arms, NodeAttributes::getAllExceptOriginalNode($node));
                }

                continue;
            }

            unset($arms[$i]);

            yield new Node\Expr\Match_($node->cond, $arms, NodeAttributes::getAllExceptOriginalNode($node));
        }
    }
}

